export function getSkillById(id: string): ProgrammingSkill | undefined {
  return PROGRAMMING_SKILLS.find(skill => skill.id === id);
}

export function getSkillsByCategory(category: string): ProgrammingSkill[] {
  return PROGRAMMING_SKILLS.filter(skill => skill.category === category);
}

export function getSkillsByExpertType(expertType: string): ProgrammingSkill[] {
  return PROGRAMMING_SKILLS.filter(skill => skill.expertType === expertType);
}

export function searchSkills(query: string): ProgrammingSkill[] {
  const lowerQuery = query.toLowerCase();
  return PROGRAMMING_SKILLS.filter(skill =>
    skill.name.toLowerCase().includes(lowerQuery) ||
    skill.keywords.some(keyword => keyword.toLowerCase().includes(lowerQuery)) ||
    skill.description.toLowerCase().includes(lowerQuery)
  );
}

export function getAllCategories(): string[] {
  const categories = new Set(PROGRAMMING_SKILLS.map(skill => skill.category));
  return Array.from(categories).sort();
}

export function getAllExpertTypes(): string[] {
  const types = new Set(PROGRAMMING_SKILLS.map(skill => skill.expertType));
  return Array.from(types).sort();
}
